F=["sessions_7d","session_change_7d","listening_minutes_7d","listening_change_7d","skip_rate","save_rate","share_rate","playlist_rate","search_rate","discovery_rate","unique_artists_7d","unique_genres_7d","days_active_14d","avg_session_minutes","subscription_age_days","support_tickets_30d","night_listening_share","completion_rate","avg_daily_sessions","weekend_usage_share","session_gap_hours","artist_concentration","genre_concentration","notification_open_rate","recommendation_click_rate","offline_downloads_30d","playlists_created_30d","social_interactions_30d","device_switch_rate","ad_skip_rate","notification_fatigue","content_diversity"]
df=pd.read_csv(D/"users.csv"); fit=df.sample(min(5000,len(df)),random_state=42).copy(); X=fit[F];y=fit.churn;tr,te=train_test_split(np.arange(len(fit)),test_size=.2,stratify=y,random_state=42)
