reg=RandomForestRegressor(n_estimators=50,max_depth=12,min_samples_leaf=5,random_state=42,n_jobs=2);reg.fit(X.iloc[tr],np.log1p(fit.ltv.iloc[tr]));lp=np.expm1(reg.predict(X.iloc[te]));true=fit.ltv.iloc[te]
axtr,axte,aytr,ayte=train_test_split(X,fit.next_action,test_size=.2,stratify=fit.next_action,random_state=42);act=RandomForestClassifier(n_estimators=50,max_depth=10,min_samples_leaf=5,class_weight="balanced",random_state=42,n_jobs=2);act.fit(axtr,aytr);ap=act.predict(axte)
sc=StandardScaler();km=KMeans(n_clusters=6,n_init=10,random_state=42).fit(sc.fit_transform(X));cent=pd.DataFrame(sc.inverse_transform(km.cluster_centers_),columns=F);score=cent.sessions_7d.rank()+cent.listening_minutes_7d.rank()+cent.discovery_rate.rank()+cent.days_active_14d.rank()-cent.skip_rate.rank();order=list(score.sort_values(ascending=False).index);names=["Daily Loyalist","Explorer","Binge Listener","Community Builder","Drifting User","Ghost / Low Activity"];mapping={c:names[j] for j,c in enumerate(order)}
for name,obj in [("churn_model.pkl",{"model":clf,"features":F}),("ltv_model.pkl",{"model":reg,"features":F}),("action_model.pkl",{"model":act,"features":F}),("segment_model.pkl",{"model":km,"scaler":sc,"mapping":mapping,"features":F})]:joblib.dump(obj,M/name)
# score full 15k/25k dataset in batches
allX=df[F];ids=km.predict(sc.transform(allX));df["segment_id"]=ids;df["segment"]=[mapping.get(int(i),"Segment") for i in ids];df["churn_probability"]=clf.predict_proba(allX)[:,1];df["predicted_ltv"]=np.expm1(reg.predict(allX));df["predicted_next_action"]=act.predict(allX);df["engagement_health"]=(1-df.churn_probability).clip(0,1)*100;df["risk"]=np.where(df.churn_probability>=.72,"CRITICAL",np.where(df.churn_probability>=.5,"HIGH",np.where(df.churn_probability>=.25,"MODERATE","LOW")))
q=df.predicted_ltv.quantile(.75)
def rec(r):
 if r.churn_probability>=.72 and r.predicted_ltv>=q:return "Priority retention: personalized re-engagement for a high-value at-risk user"
 if r.skip_rate>.55 or r.ad_skip_rate>.65:return "Improve first-result matching and reduce skip-heavy sessions"
 if r.discovery_rate<.25 or r.content_diversity<.30:return "Increase discovery and broaden personalized content exposure"
 if r.sessions_7d<3 or r.session_change_7d<-.25:return "Re-engage with a lightweight personalized entry point"
 if r.notification_fatigue>.65:return "Reduce notification pressure and optimize message timing"
 return "Maintain experience and grow engagement"
df["recommendation"]=[rec(r) for r in df.itertuples()];df.to_csv(D/"audience_predictions.csv",index=False);df[F+["churn","ltv","next_action"]].sample(1200,random_state=42).to_csv(D/"training_template.csv",index=False);df[F+["churn","ltv","next_action"]].sample(600,random_state=7).to_csv(D/"test_template.csv",index=False)
